import numpy as np
y=np.array([2.,3,5,7,11]); good=np.array([2.2,2.8,5.4,6.7,10.5]); bad=np.full_like(y,20.)
def r2(p): return 1-np.sum((y-p)**2)/np.sum((y-y.mean())**2)
for name,p in [('good',good),('bad out-of-sample model',bad),('mean baseline',np.full_like(y,y.mean()))]: print(name,'R²=',round(r2(p),3),'RMSE=',round(np.sqrt(np.mean((y-p)**2)),3))
